    headline: "headline",
    serverCount: "server-count",
    statRequests: "stat-requests",
    statQps: "stat-qps",
    statNxdomain: "stat-nxdomain",
    statServfail: "stat-servfail",
    statTransfers: "stat-transfers",
    statNote: "stat-note",
