    const v = state.view;
    const cur = p.getState();
    const custom = v.start && v.end ? { start: v.start, end: v.end } : null;
    const same = cur.hours === v.hours && (cur.customRange ? custom && cur.customRange.start === custom.start && cur.customRange.end === custom.end : !custom);
